class NegativeError(Exception):
    pass

def safe_div(a, b):
    if a < 0 or b < 0:
        raise NegativeError("不允许负数")
    try:
        return a / b
    except ZeroDivisionError as e:
        print(f"警告: {e}")
        return None

print(safe_div(6, 3))     # 2.0
print(safe_div(1, 0))     # 警告 + None
try:
    safe_div(-1, 2)
except NegativeError as e:
    print("捕获:", e)

依次输出 2.0、警告提示与 None、捕获: 不允许负数。
